// Parse and validate character intent request
const request = $input.first().json;

// Required fields validation
if (!request.character_input || !request.character_class || !request.character_level) {
  return [{
    json: {
      error: 'Missing required fields: character_input, character_class, character_level',
      status: 'invalid_request',
      timestamp: new Date().toISOString()
    }
  }];
}

// Extract character context and history
const characterContext = {
  input: request.character_input,
  class: request.character_class,
  level: request.character_level,
  party_composition: request.party_composition || [],
  current_quest: request.current_quest || '',
  play_style: request.play_style || 'balanced',
  previous_automations: request.previous_automations || [],
  success_patterns: request.success_patterns || [],
  character_preferences: request.character_preferences || {},
  session_context: request.session_context || {},
  timestamp: new Date().toISOString()
};

// Define semantic analysis configuration
const analysisConfig = {
  ...characterContext,
  analysis_depth: request.analysis_depth || 'comprehensive',
  include_code_generation: request.include_code_generation !== false,
  include_explanations: request.include_explanations !== false,
  learning_mode: request.learning_mode || 'adaptive',
  ai_provider: request.ai_provider || 'deepseek'
};

return [{
  json: analysisConfig
}];

// Build character knowledge base and context
const config = $input.first().json;

// Character class-specific knowledge bases
const classKnowledge = {
  'fighter': {
    primary_focus: ['combat', 'protection', 'tank', 'damage'],
    common_intents: ['protect party', 'deal damage', 'defend', 'lead'],
    automation_patterns: ['combat_rotation', 'protective_aura', 'taunt_management'],
    spell_types: [],
    key_abilities: ['strength', 'constitution', 'weapon_mastery']
  },
  'wizard': {
    primary_focus: ['magic', 'control', 'damage', 'support'],
    common_intents: ['cast spells', 'control battlefield', 'support party', 'solve puzzles'],
    automation_patterns: ['spell_rotation', 'concentration_management', 'buff_stack'],
    spell_types: ['evocation', 'illusion', 'enchantment', 'divination'],
    key_abilities: ['intelligence', 'wisdom', 'spell_mastery']
  },
  'cleric': {
    primary_focus: ['healing', 'support', 'divine', 'protection'],
    common_intents: ['heal party', 'remove curses', 'protect from evil', 'channel divinity'],
    automation_patterns: ['healing_prioritization', 'buff_management', 'condition_removal'],
    spell_types: ['divination', 'evocation', 'abjuration', 'necromancy'],
    key_abilities: ['wisdom', 'charisma', 'divine_connection']
  },
  'rogue': {
    primary_focus: ['stealth', 'damage', 'skills', 'utility'],
    common_intents: ['sneak attack', 'disarm traps', 'scout ahead', 'pick locks'],
    automation_patterns: ['stealth_positioning', 'opportunity_attack', 'skill_check_optimization'],
    spell_types: [],
    key_abilities: ['dexterity', 'intelligence', 'stealth_mastery']
  },
  'paladin': {
    primary_focus: ['divine', 'protection', 'healing', 'combat'],
    common_intents: ['protect allies', 'smite evil', 'heal wounds', 'uphold honor'],
    automation_patterns: ['divine_smite', 'lay_on_hands', 'aura_management'],
    spell_types: ['abjuration', 'evocation', 'divination'],
    key_abilities: ['strength', 'charisma', 'divine_power']
  }
};

// Get character class knowledge or use generic
const characterKnowledge = classKnowledge[config.class.toLowerCase()] || {
  primary_focus: ['general'],
  common_intents: ['help party', 'improve skills'],
  automation_patterns: ['basic_automation'],
  spell_types: [],
  key_abilities: ['balanced']
};

// Build comprehensive context for AI analysis
const enhancedContext = {
  ...config,
  character_knowledge: characterKnowledge,
  semantic_patterns: {
    protection_keywords: ['protect', 'defend', 'shield', 'guard', 'save', 'rescue', 'help'],
    combat_keywords: ['attack', 'damage', 'fight', 'kill', 'destroy', 'defeat', 'battle'],
    healing_keywords: ['heal', 'cure', 'restore', 'mend', 'recover', 'aid', 'support'],
    utility_keywords: ['help', 'assist', 'prepare', 'organize', 'manage', 'optimize'],
    exploration_keywords: ['scout', 'search', 'investigate', 'explore', 'track', 'navigate']
  },
  business_logic_mapping: {
    'protect party': 'protection_automation_system',
    'heal when hurt': 'health_monitoring_system',
    'deal more damage': 'combat_optimization_system',
    'be prepared': 'buff_and_preparation_system',
    'support allies': 'support_automation_system'
  }
};

return [{
  json: enhancedContext
}];

// Create comprehensive semantic analysis prompt
const context = $input.first().json;

const semanticPrompt = `
You are an expert Semantic Code Understanding Engine for D&D character automation. Your role is to understand character intent beyond literal requests and translate it into comprehensive technical solutions.

## Character Profile:
- Class: ${context.class}
- Level: ${context.level}
- Play Style: ${context.play_style}
- Party Composition: ${context.party_composition.join(', ')}
- Current Quest: ${context.current_quest}

## Character Input: "${context.input}"

## Previous Success Patterns:
${context.success_patterns.length > 0 ? context.success_patterns.join(', ') : 'No previous patterns'}

## Your Task:
1. **Semantic Understanding**: What is the character REALLY trying to accomplish?
2. **Business Logic Translation**: Convert character intent into technical requirements
3. **Solution Architecture**: Design a complete automation solution
4. **Learning Integration**: Incorporate previous success patterns
5. **Character-Appropriate Explanation**: Provide explanations the character understands

## Response Format (JSON):
{
  "semantic_analysis": {
    "true_intent": "The deeper meaning behind the character's words",
    "business_goal": "What the character wants to accomplish in game terms",
    "emotional_context": "The emotional state driving this request",
    "urgency_level": "immediate/medium/low",
    "complexity": "simple/medium/complex"
  },
  "technical_requirements": {
    "automation_type": "protection/healing/combat/utility/exploration",
    "trigger_conditions": ["list of conditions that trigger the automation"],
    "actions_required": ["list of specific actions to implement"],
    "dependencies": ["other systems or data needed"],
    "success_metrics": ["how to measure success"]
  },
  "solution_architecture": {
    "components": ["major components needed"],
    "data_flow": "how information moves through the system",
    "integration_points": ["connections to other systems"],
    "error_handling": "how to handle failures or edge cases"
  },
  "character_friendly_explanation": {
    "what_it_does": "simple explanation for the character",
    "why_it_helps": "how this achieves their goal",
    "when_it_activates": "clear conditions for activation",
    "what_character_needs_to_do": "any manual actions required"
  },
  "learning_opportunities": {
    "patterns_to_learn": ["what patterns this system should learn"],
    "optimization_points": ["how this can be improved over time"],
    "adaptation_suggestions": ["how to adapt to different situations"]
  }
}

Focus on understanding the CHARACTER's perspective, not just the technical requirements. Think like a wise mentor who understands both the game world and the technical implementation.`;

return [{
  json: {
    ...context,
    deepseek_prompt: semanticPrompt,
    analysis_type: 'semantic_understanding'
  }
}];

// Process DeepSeek response and extract semantic understanding
const response = $input.first().json;
const originalContext = items.find(item => item.json.deepseek_prompt)?.json;

if (!response.choices || !response.choices[0]?.message?.content) {
  return [{
    json: {
      error: 'Invalid response from DeepSeek API',
      status: 'ai_error',
      timestamp: new Date().toISOString()
    }
  }];
}

try {
  const analysisResult = JSON.parse(response.choices[0].message.content);

  // Enhance analysis with metadata
  const enhancedResult = {
    timestamp: new Date().toISOString(),
    character_id: originalContext.character_id || 'unknown',
    session_id: originalContext.session_id || 'unknown',
    original_input: originalContext.input,
    character_class: originalContext.class,
    analysis_result: analysisResult,
    metadata: {
      ai_provider: 'deepseek',
      model: 'deepseek-chat',
      processing_time: response.usage?.total_time || 0,
      tokens_used: response.usage?.total_tokens || 0,
      analysis_depth: originalContext.analysis_depth,
      learning_mode: originalContext.learning_mode
    },
    next_steps: {
      requires_code_generation: analysisResult.technical_requirements ? true : false,
      requires_pattern_learning: analysisResult.learning_opportunities ? true : false,
      requires_solution_architecture: analysisResult.solution_architecture ? true : false
    }
  };

  return [{
    json: enhancedResult
  }];

} catch (error) {
  return [{
    json: {
      error: 'Failed to parse AI response',
      details: error.message,
      raw_response: response.choices[0].message.content,
      status: 'parsing_error',
      timestamp: new Date().toISOString()
    }
  }];
}

// Trigger code generation workflow
const analysis = $input.first().json;

// Prepare code generation request
const codeGenerationRequest = {
  semantic_analysis: analysis.analysis_result,
  character_context: {
    class: analysis.character_class,
    input: analysis.original_input,
    preferences: analysis.metadata
  },
  technical_requirements: analysis.analysis_result.technical_requirements,
  solution_architecture: analysis.analysis_result.solution_architecture,
  character_friendly: analysis.analysis_result.character_friendly_explanation,
  workflow_request: {
    source: 'semantic_understanding_engine',
    priority: 'normal',
    include_explanations: true,
    include_error_handling: true,
    include_testing: true
  }
};

return [{
  json: codeGenerationRequest,
  // Store for response
  original_analysis: analysis
}];

// Pattern learning request
const analysis = $input.first().json;

if (analysis.analysis_result.learning_opportunities) {
  const learningRequest = {
    character_id: analysis.character_id,
    session_id: analysis.session_id,
    semantic_analysis: analysis.analysis_result.semantic_analysis,
    learning_opportunities: analysis.analysis_result.learning_opportunities,
    success_patterns: analysis.analysis_result.learning_opportunities.patterns_to_learn || [],
    timestamp: analysis.timestamp,
    source: 'semantic_understanding_engine'
  };

  return [{
    json: learningRequest
  }];
}

return [{
  json: { message: 'No learning opportunities identified' }
}];

// Final response preparation
const analysis = $input.first().json;

const response = {
  status: 'success',
  timestamp: new Date().toISOString(),
  character_intent_understood: analysis.analysis_result.semantic_analysis?.true_intent || 'Intent unclear',
  business_goal: analysis.analysis_result.semantic_analysis?.business_goal || 'Goal identification failed',
  character_friendly_explanation: analysis.analysis_result.character_friendly_explanation || {
    what_it_does: 'Automated assistance system',
    why_it_helps: 'Achieves your objectives more efficiently',
    when_it_activates: 'Based on your needs',
    what_character_needs_to_do: 'Monitor and provide feedback'
  },
  automation_type: analysis.analysis_result.technical_requirements?.automation_type || 'general',
  complexity_level: analysis.analysis_result.semantic_analysis?.complexity || 'medium',
  next_actions: {
    code_generation_triggered: analysis.next_steps?.requires_code_generation || false,
    pattern_learning_triggered: analysis.next_steps?.requires_pattern_learning || false,
    architecture_design_triggered: analysis.next_steps?.requires_solution_architecture || false
  },
  metadata: {
    processing_time: analysis.metadata?.processing_time || 0,
    tokens_used: analysis.metadata?.tokens_used || 0,
    ai_provider: analysis.metadata?.ai_provider || 'deepseek'
  }
};

return [{
  json: response
}];

// Error handling
const error = $input.first().json;

const errorResponse = {
  status: 'error',
  timestamp: new Date().toISOString(),
  error: error.error || 'Unknown error occurred',
  details: error.details || 'No additional details available',
  character_friendly_message: 'I had trouble understanding your request. Could you try explaining it differently?',
  suggestions: [
    'Try being more specific about what you want to accomplish',
    'Tell me about your character class and current situation',
    'Describe what you want to achieve in simple terms'
  ]
};

return [{
  json: errorResponse
}];
